import json, re, os
data = json.load(open('deliverable/citations.json'))
idx = open('library/INDEX.md').read()
enum = {'in force','superseded','vacated'}
keys = {'cite','library_file','proposition','status_checked'}
errs = []
for i, e in enumerate(data):
    if set(e.keys()) != keys: errs.append(f'{i}: keys {set(e.keys())^keys}')
